// client/src/features/dashboard/organizer/OrganizerDashboard.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const OrganizerDashboard = () => {
  const [events, setEvents] = useState([]);
  const [error, setError]   = useState(null);

  const fetchMyEvents = async () => {
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get(
        '/api/organizer/my-events',            // ← relative URL
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEvents(res.data.events);
    } catch (err) {
      setError('Failed to fetch events');
    }
  };

  useEffect(() => { fetchMyEvents(); }, []);

  return (
    <div className="container">
      <div className="card">
        <h2>Organizer Dashboard</h2>
        <div style={{ marginBottom: '1rem' }}>
          <Link to="/organizer/create-event"><button className="btn">Create New Event</button></Link>
          <button className="btn" onClick={fetchMyEvents} style={{ marginLeft: '1rem' }}>
            Manage Events
          </button>
        </div>
        {error && <p style={{ color:'red' }}>{error}</p>}
        {events.length === 0 && !error && <p>No events yet.</p>}
        <ul>
          {events.map(evt => (
            <li key={evt._id}>
              <strong>{evt.title}</strong> — {new Date(evt.date).toLocaleString()}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default OrganizerDashboard;
